 test("yearly/feb29 skips nonleap",()->dates(get(s("2024-02-29T09:00","2024-02-29T10:00",UTC,false,r("yearly",1,3)),"2024-01-01T00:00","2033-01-01T00:00",UTC),UTC,"2024-02-29T09:00","2028-02-29T09:00","2032-02-29T09:00"));
